"""Strict bounded historical evidence tool; no SQL or raw HA formats exposed."""
import json
from historical import OPS
WINDOW={'anyOf':[{'type':'string','maxLength':160},{'type':'object','properties':{'start':{'type':'string'},'end':{'type':'string'}},'required':['start','end'],'additionalProperties':False}]}
DEFINITIONS=[{'name':'history_read','description':'Retrieve/calculate bounded historical facts using Home Model targets and explicit local time windows. Operations cover sensor statistics/trends, durations, transitions/counts, automation/script runs/traces, coarse presence history, comparisons and multi-signal causal evidence. UNKNOWN/partial history does not mean nothing happened. Automation enabled state is not execution. Keep source details internal unless relevant; answer naturally.','input_schema':{'type':'object','properties':{'operation':{'type':'string','enum':sorted(OPS)},'target':{'type':'string','maxLength':150},'window':WINDOW,'options':{'type':'object','properties':{'property':{'type':'string','enum':['state','hvac_action','temperature','current_temperature','brightness','percentage','volume_level','last_triggered','preset_mode']},'state':{'type':'string'},'to_state':{'type':'string'},'from_state':{'type':'string'},'presence':{'type':'string','enum':['HOME','OFFICE','AWAY','UNKNOWN']},'run_id':{'type':'string','maxLength':128},'other_window':WINDOW,'requested_metric':{'type':'string','enum':['minimum','maximum']},'offset':{'type':'integer','minimum':0,'maximum':6000},'limit':{'type':'integer','minimum':1,'maximum':80}},'additionalProperties':False}},'required':['operation','target'],'additionalProperties':False}}]
async def execute(provider,args):
 if provider is None:return json.dumps({'status':'HISTORY_UNAVAILABLE','message':'Historical evidence is disabled.'})
 return json.dumps(provider.projection(await provider.query(**args)),default=str)
